<?php
namespace App\Policies;
use App\Models\RecurringPlan; use App\Models\User;
class RecurringPlanPolicy {private function p(User $u,string $p):bool{return $u->hasPermission($p);} public function viewAny(User $u):bool{return $this->p($u,'recurring_plans.view');} public function view(User $u,RecurringPlan $m):bool{return $this->p($u,'recurring_plans.view');} public function create(User $u):bool{return $this->p($u,'recurring_plans.create');} public function update(User $u,RecurringPlan $m):bool{return in_array($m->status,['draft','paused'],true)&&$this->p($u,'recurring_plans.edit');} public function delete(User $u,RecurringPlan $m):bool{return in_array($m->status,['draft','cancelled'],true)&&$this->p($u,'recurring_plans.delete');} public function approve(User $u,RecurringPlan $m):bool{return $m->status==='draft'&&$this->p($u,'recurring_plans.approve');} public function pause(User $u,RecurringPlan $m):bool{return $m->status==='active'&&$this->p($u,'recurring_plans.edit');} public function resume(User $u,RecurringPlan $m):bool{return $m->status==='paused'&&$this->p($u,'recurring_plans.edit');} public function cancel(User $u,RecurringPlan $m):bool{return !in_array($m->status,['cancelled','completed'],true)&&$this->p($u,'recurring_plans.approve');}}
